<script setup lang="ts">
import {ref} from 'vue'
import {useRouter} from 'vue-router'
import {IconArrowBigUp,IconPlus} from '@tabler/icons-vue'
import Panel from '../components/Panel.vue';import Workflow from '../components/Workflow.vue'
import {api,run,refresh,select,current,busy,notify} from '../store'
const router=useRouter();const input=ref<HTMLInputElement>();const title=ref('');const dragging=ref(false)
async function uploadFile(file:File,source='user_upload'){await run(async()=>{const body=new FormData();body.append('file',file);body.append('title',title.value.trim()||file.name.replace(/\.[^.]+$/,''));body.append('source_kind',source);const seal=await api('/seals',{method:'POST',body});await refresh();select(seal.id);notify('原始图像已写入数据库，可继续印文提取。')})}
function change(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(file)uploadFile(file)}
function drop(e:DragEvent){dragging.value=false;const file=e.dataTransfer?.files[0];if(file)uploadFile(file)}
async function sample(){const res=await fetch('/api/test-sample');if(res.ok)await uploadFile(new File([await res.blob()],'合成测试印谱.png',{type:'image/png'}),'synthetic_test')}
</script>
<template><div class="upload-grid"><Panel title="上传古印谱原始图像" note="原始图像入口 · 数据采集"><div class="dropzone" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave="dragging=false" @drop.prevent="drop"><IconArrowBigUp :size="76" :stroke-width="1"/><h2>拖拽古印谱图像至此处</h2><p>支持 JPG / PNG / WebP，最大15MB，建议高分辨率扫描</p><button class="primary" :disabled="busy" @click="input?.click()"><IconPlus :size="18"/>选择本地图像</button><input ref="input" type="file" accept="image/png,image/jpeg,image/webp" hidden @change="change"><label class="upload-name">印谱名称<input v-model="title" placeholder="可选，默认使用文件名" maxlength="150"></label></div><div class="sample-cards"><div><img src="/assets/original.png" alt="古籍印谱参考"><span>古籍印谱 · 参考素材</span></div><div><img src="/assets/restored.png" alt="朱文印蜕参考"><span>朱文印蜕 · 参考素材</span></div><button @click="sample" :disabled="busy"><img :src="'/api/test-sample'" alt="合成测试样本"><span>导入合成测试样本</span></button></div></Panel><Panel title="扫描件识别与校验" note="图像校验 · 原稿归档"><div class="upload-preview"><span class="image-tag">{{current?'当前已归档图像':'待上传 · 参考素材'}}</span><img :src="current?.original_url||'/assets/original.png'" alt="印谱上传预览"></div><dl class="data-list"><div><dt>图像分辨率</dt><dd>{{current?`${current.artifacts[0]?.metadata.width} × ${current.artifacts[0]?.metadata.height}`:'等待上传'}}</dd></div><div><dt>数据来源</dt><dd>{{current?.source_kind==='synthetic_test'?'合成测试样本':current?'用户上传':'尚无真实数据'}}</dd></div><div><dt>存储状态</dt><dd>{{current?'MySQL已归档':'等待上传'}}</dd></div><div><dt>印章边界</dt><dd>印文区域提取</dd></div><div><dt>图像质量</dt><dd>文件与像素校验</dd></div></dl><button class="primary full" :disabled="!current||busy" @click="router.push('/recognition')">开始印文提取 →</button></Panel></div><Panel class="workflow-panel" title="标准化处理流程" note="数据输入—图像处理—三维实体闭环"><Workflow :active="0"/></Panel></template>
